amis_schema:
{
  "type": "page",
  "cssVars": {
    "--text--muted-color": "#bebfc4"
  },
  "css": {
    ".antd-Service": {
      "flex-grow": "1"
    },
    ".antd-Cards": {
      "height": "100%"
    },
    ".antd-Cards .antd-Cards-toolbar": {
      "padding-top": "0.5rem",
      "padding-bottom": "0.5rem",
      "padding-left": "1rem",
      "padding-right": "1rem",
      "--tw-bg-opacity": "1",
      "background-color": "rgb(243 244 246 / var(--tw-bg-opacity))",
      "--tw-border-opacity": "1",
      "border-color": "rgb(209 213 219 / var(--tw-border-opacity))",
      "border-style": "solid",
      "border-bottom-width": "1px"
    },
    ".antd-Cards .antd-Cards-body": {
      "margin": "0.25rem"
    },
    ".antd-Card-toolbar .ant-ribbon-wrapper": {
      "position": "absolute",
      "top": "-14px",
      "right": "0"
    },
    ".antd-Cards .antd-Card .antd-Card-heading .antd-Card-avtar, .antd-Cards .antd-Card .antd-Card-heading .antd-Card-avtarText": {
      "min-width": "50px",
      "min-height": "50px",
      "border-radius": "6px",
      "width": "50px",
      "height": "50px"
    },
    ".antd-Cards .antd-Card .antd-Card-meta": {
      "overflow": "hidden"
    },
    ".antd-Cards .antd-Card .antd-Card-meta .antd-Card-subTitle": {
      "-webkit-line-clamp": "1",
      "max-height": "calc(var(--fontSizeBase) * var(--lineHeightBase) * 1)",
      "min-height": "calc(var(--fontSizeBase) * var(--lineHeightBase) * 1)"
    },
    ".steedos-object-table.steedos-crud-mode-cards .antd-Cards .antd-Cards-body .antd-Card .antd-Card-body": {
      "padding-left": "0px",
      "padding-right": "0px",
      "padding-top": "0px",
      "margin-top": "0px",
      "padding-bottom": "0px"
    },
    ".steedos-object-table.steedos-crud-mode-cards .antd-Cards .antd-Cards-body .antd-Card": {
      "padding-top": "2px"
    },
    ".antd-Card-actions a[disabled]": {
      "box-shadow": "none",
      "cursor": "not-allowed"
    },
    ".antd-Card-actions a[disabled]:hover": {
      "color": "rgba(0,0,0,.25)"
    }
  },
  "data": {
    "items": [
      {
        "category": "应用",
        "label": "@steedos-labs/oa",
        "name": "@steedos-labs/oa",
        "description": "OA办公基础模块。",
        "license": "CE",
        "version": "6.3.12",
        "homepage": "https://www.steedos.com",
        "icon": "https://unpkg.steedos.cn/@salesforce-ux/design-system@2.22.2/assets/icons/standard/template_120.png"
      },
      {
        "category": "应用",
        "label": "@steedos-labs/crm",
        "name": "@steedos-labs/crm",
        "license": "EE",
        "description": "企业CRM销售管理。",
        "version": "6.3.12",
        "icon": "https://unpkg.steedos.cn/@salesforce-ux/design-system@2.22.2/assets/icons/standard/template_120.png"
      },
      {
        "category": "应用",
        "name": "@steedos-labs/cms",
        "label": "@steedos-labs/cms",
        "license": "EE",
        "version": "6.3.12",
        "icon": "https://unpkg.steedos.cn/@salesforce-ux/design-system@2.22.2/assets/icons/standard/template_120.png"
      },
      {
        "category": "插件",
        "name": "@steedos-labs/plugin-ai",
        "label": "@steedos-labs/plugin-ai",
        "license": "CE",
        "version": "6",
        "icon": "https://unpkg.steedos.cn/@salesforce-ux/design-system@2.22.2/assets/icons/standard/template_120.png"
      },
      {
        "category": "插件",
        "name": "@steedos-labs/plugin-dingtalk",
        "label": "@steedos-labs/plugin-dingtalk",
        "license": "CE",
        "version": "6.3.12",
        "icon": "https://unpkg.steedos.cn/@salesforce-ux/design-system@2.22.2/assets/icons/standard/template_120.png"
      }
    ]
  },
  "body": {
    "type": "service",
    "id": "service-packages",
    "dataProvider": "window.addEventListener('message', function(message) { try{let data = JSON.parse(message.data); if(data.type === 'InstalledPackages'){const installedPackagesName = []; data.installPackages.forEach(function(item){installedPackagesName.push(item.name)});setData({installedPackages: data.installPackages, installedPackagesName: installedPackagesName})}else if(data.type === 'InstalledPackage'){const installedPackagesName = []; data.installPackages.forEach(function(item){installedPackagesName.push(item.name)});setData({installing: false, installingName: '', installedPackages: data.installPackages, installedPackagesName: installedPackagesName})}}catch(e){console.error(e)}})",
    "body": {
      "type": "cards",
      "source": "$items",
      "card": {
        "body": [
          {
            "type": "tpl",
            "tpl": "<div class='antd-Card-heading bg-white'><span class='antd-Card-avtar pull-left thumb-md m-r slds-icon slds-icon_container slds-icon-standard-approval h-auto' ><img class='antd-Card-img'src='${icon}' /></span><div class='antd-Card-meta'><div class='antd-Card-title'><a href='${homepage}' target='_blank'><span class='antd-TplField' title='${label}'><span>${label}</span></span></a></div><div class='antd-Card-subTitle'><span class='antd-TplField' title='${description}'><span>${description}</span></span></div><div class='antd-Card-desc'><span class='antd-TplField'><span><span class='bg-${status === 'enable' ? 'green': 'gray'}-300 rounded-full px-2 py-0.5 mt-2 inline-block'>${category}</span><span class='text-gray-600 px-2 py-0.5 mt-2 inline-block float-right'><span class='${license == 'CE' ? 'hidden': ''} antd-Tag antd-Tag--normal antd-Tag--normal--success antd-Tag--normal--hasColor rounded-full'><span class='antd-Tag-text'>${license}</span></span></span></span></span></div></div></div>"
          }
        ],
        "actions": [
          {
            "type": "progress",
            "animate": true,
            "value": 100,
            "className": "w-full m-3",
            "visibleOn": "${installing && installingName === name}",
            "showLabel": false
          },
          {
            "type": "button",
            "level": "link",
            "label": "已安装",
            "disabled": true,
            "visibleOn": "${ARRAYINCLUDES(installedPackagesName, name)}"
          },
          {
            "type": "button",
            "level": "link",
            "label": "安装",
            "visibleOn": "${installing != true && ARRAYINCLUDES(installedPackagesName, name) != true}",
            "onEvent": {
              "click": {
                "actions": [
                  {
                    "actionType": "setValue",
                    "componentId": "service-packages",
                    "args": {
                      "value": {
                        "installing": true,
                        "installingName": "${name}"
                      }
                    }
                  },
                  {
                    "actionType": "custom",
                    "script": "console.log('postMessage', Object.assign({type: 'install'}, {config: event.data}));window.parent.postMessage(Object.assign({type: 'install'}, {config: event.data}), '*')"
                  }
                ]
              }
            }
          }
        ]
      }
    }
  },
  "onEvent": {
    "init": {
      "actions": [
        {
          "actionType": "custom",
          "script": "window.parent.postMessage({type:'amis:load', data: {'iframeId': 'app-store'}}, '*'); window.parent.postMessage({type:'amis:getInstalled', data: {'iframeId': 'app-store'}}, '*');"
        }
      ]
    }
  }
}
